 21	function parserTests() {
 22	  const parsed = Intake.parseReport(JSON.stringify(valid()));
 23	  assert.equal(parsed.computer.hostname, 'LAPTOP-01');
 24	  assert.equal(parsed.computer.serialNumber, 'ABC123');
