 42	function matchingTests() {
 43	  const report = Intake.parseReport(JSON.stringify(valid({
 44	    person: { displayName: 'Alex Example', email: 'alex@example.com', accountName: 'alex', domain: 'ACME' },
 45	    computer: { hostname: 'LAPTOP-01', windowsDomain: 'ACME', manufacturer: 'Dell', serialNumber: 'ABC123' }
 46	  })));
