 50	    byEmail: { id: 'byEmail', type: 'person', name: 'Alex E', email: 'ALEX@example.com' },
 51	    byAccount: { id: 'byAccount', type: 'person', name: 'Alex Account', accountName: 'alex', domain: 'acme' },
 52	    byName: { id: 'byName', type: 'person', name: 'Alex Example' }
 53	  }, workspaces: { default: { name: 'Default', categories: {}, entityTypes: {}, entities: {} } }, currentWorkspaceId: 'default' };
 54	  const before = JSON.stringify(data);
 55	  const plan = Intake.createPlan(report, data);
 56	  assert.equal(JSON.stringify(data), before, 'preview must not mutate source data');
 57	  assert.equal(Object.isFrozen(plan), true);
 58	  assert.equal(plan.computer.status, 'conflict');
