 75	  assert.ok(candidate.entityTypes.computer.fields.some(field => field.name === 'hostname'), 'confirmed import must add a visible hostname field');
 76	  assert.ok(candidate.entityTypes.computer.fields.some(field => field.name === 'serialNumber'), 'confirmed import must add a visible serial field');
 77	  assert.ok(candidate.entityTypes.person.fields.some(field => field.name === 'accountName'), 'confirmed import must add visible person identity fields');
 78	  assert.deepEqual(candidate.workspaces.default.entityTypes, candidate.entityTypes, 'confirmed schema migration must persist in the active workspace');
 79	  assert.ok(plan.computer.changes.some(change => change.field === 'hostname' && change.before === 'OTHER' && change.after === 'LAPTOP-01'));
 80	
 81	  const identityConflict = Intake.createPlan(Intake.parseReport(JSON.stringify(valid({
 82	    person: { email: 'alex@example.com', upn: 'other@example.com' },
 83	    computer: { manufacturer: 'Dell', serialNumber: 'ABC123' }
 84	  }))), { ...data, entities: { ...data.entities, byUpn: { id: 'byUpn', type: 'person', name: 'Other', upn: 'other@example.com' } } });
