 86	  assert.deepEqual(identityConflict.person.candidates.map(x => x.id), ['byEmail', 'byUpn']);
 87	
 88	  const serialOnly = Intake.createPlan(Intake.parseReport(JSON.stringify(valid({ computer: { manufacturer: 'Dell', serialNumber: 'ABC123' } }))), data);
