 91	  const hostnameOnly = Intake.createPlan(Intake.parseReport(JSON.stringify(valid({ computer: { hostname: 'LAPTOP-01', windowsDomain: 'ACME' } }))), data);
 92	  assert.equal(hostnameOnly.computer.status, 'update');
